// VibeField · the loading window's splash, the runtime (splash/, 2026-10-09).
//
// The wormhole lab's loading window, cut down to what it shows: the field behind the window
// and the living mark at its centre, one canvas, one look. bake.mjs specializes the lab's own
// shader to a look (every parameter a constant, so the compiler folds what the look leaves
// off) and writes this file with the look's data in BAKED (above). What it costs:
//
//   - the well's march runs once per size, into a texture of depths (splashDepth): a frame
//     only paints the field from it (splashField)
//   - per frame: one 4× multisampled pass for the mark, the size of the mark (≈ 200 × 110 px),
//     and one pass over the window (the field, then the mark laid over) — two small uniform
//     writes, two passes, one submit
//   - at most `fps` frames a second (60; a 120 Hz screen draws every other refresh), none
//     while the page is hidden, and one only, at rest, under reduced motion
//   - the field's backing store stops growing at BUDGET device pixels (a 14-inch MacBook Pro's
//     screen, full size, is under it; a 5K display draws at ~0.64 of its pixels)
//
//   const splash = await createSplash(canvas, { fps: 60 });
//   splash.stop(); splash.start(); splash.destroy();
//
// The reveal (2026-10-27): created with { transparent: true } the canvas is premultiplied, and
// splash.reveal() (or setReveal(0 … 1) frame by frame) opens the window from its centre onto
// what lies under the canvas — a hole torn by noise, lit at its edge (entry.wgsl revealAt).

const DEG = Math.PI / 180;
const TAU = 2 * Math.PI;
const wrapTau = (a) => a - TAU * Math.floor(a / TAU);
const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));

// The lab's animate() (src/mark.js), only the phases the splash's uniforms take,
// line for line; bake.mjs checks the uniforms these give against the lab's own pack() at many
// moments before it writes this file.
export function phases(C, seconds, pose) {
  const L = C.loopSeconds;
  const t = L > 0 ? seconds - L * Math.floor(seconds / L) : seconds;
  const quant = (degPerSec, period) => (L > 0 ? (Math.round((degPerSec * L) / period) * period) / L : degPerSec);
  const rot = (degPerSec, period = 360) => wrapTau(quant(degPerSec, period) * t * DEG);
  const hz = (f) => (L > 0 ? Math.round(f * L) / L : f);
  const osc = (f) => Math.sin(2 * Math.PI * hz(f) * t);
  const cyc = (f) => {
    const x = hz(f) * t;
    return x - Math.floor(x);
  };
  const turns = (degPerSec, period = 720) => {
    const x = (quant(degPerSec, period) * t) / period;
    return x - Math.floor(x);
  };
  const linePeriod = 360 / gcd(C.lines, C.accents > 0 ? C.accents : C.lines);
  const flow = rot(C.flowSpin, linePeriod);
  const palRot = wrapTau(rot(C.flowSpin + C.palSpin) - flow);
  let grainSeed = C.grainFps > 0 ? Math.floor(t * C.grainFps) : 0;
  if (L > 0 && C.grainFps > 0) grainSeed %= Math.max(1, Math.round(L * C.grainFps));

  const k = Math.max(C.halfTwists, 1);
  const travel = quant(C.twistSpin, 720 / k) * t * DEG;
  const eased = travel - C.twistEase * Math.sin(2 * travel);
  const moving = C.twistSpin !== 0 ? 1 : 0;
  const pulse = C.pulseSync > 0 && moving ? -((travel / Math.PI) * C.pulseSync) : cyc(C.pulseSpeed);
  const m = Math.max(1, Math.round(C.palCount));
  const crossings = L > 0 ? Math.round((quant(C.twistSpin, 720 / k) * L) / 180) : 0;
  const perCrossing = (step, turn) => (crossings > 0 ? (turn * Math.max(1, Math.round((crossings * step) / turn))) / crossings : step);
  let rise;
  if (C.riseSync > 0 && moving) {
    rise = (eased / Math.PI) * perCrossing(C.riseSync, m);
  } else {
    let r = C.riseRate;
    if (L > 0 && r !== 0) r = (Math.sign(r) * Math.max(1, Math.round((Math.abs(r) * L) / m)) * m) / L;
    rise = r * t;
  }
  rise -= m * 256 * Math.floor(rise / (m * 256));
  let ring = 0;
  if (C.ringRadial > 0) {
    const turn = 1 / C.ringRadial;
    let tr;
    if (C.ringSync > 0 && moving) {
      tr = (eased / Math.PI) * perCrossing(C.ringSync / m, 1);
    } else {
      let r = C.ringFlow / turn;
      if (L > 0 && r !== 0) r = (Math.sign(r) * Math.max(1, Math.round(Math.abs(r) * L))) / L;
      tr = r * t;
    }
    ring = (tr - Math.floor(tr)) * turn;
  }
  const runPeriod = L > 0 ? L : 3600;
  const runClock = (t - runPeriod * Math.floor(t / runPeriod)) / runPeriod;

  const ls = C.livSpeed;
  const REST_TWIST = 1.5 * Math.PI;
  let livTwist;
  let livTravel = turns(ls * C.livEdgeSpeed * 0.025 * 360, 360);
  let livDrift = turns(ls * C.livDrift * 0.09 * 360, 360);
  let livBreath = 1 + osc((0.72 * ls) / (2 * Math.PI)) * C.livBreathe * 0.035;
  if (pose === "at rest") {
    livTwist = wrapTau(REST_TWIST + C.livRestTwist * DEG);
    livTravel = C.livRestLights - Math.floor(C.livRestLights);
    livDrift = 0;
    livBreath = 1;
  } else if (pose === "slow lap") {
    livTwist = wrapTau(REST_TWIST + quant((ls * 0.175 * 180) / Math.PI, 360) * t * DEG);
  } else {
    const half = (quant((ls * C.livRoll * 180) / Math.PI, 360) * t) / 180;
    const kk = Math.floor(half);
    const f = half - kk;
    livTwist = wrapTau(REST_TWIST + Math.PI * (kk + f - (C.livLinger * Math.sin(2 * Math.PI * f)) / (2 * Math.PI)));
  }
  return { flow, palRot, pulse: pulse - Math.floor(pulse), rise, ring, runClock, grainSeed: grainSeed + 1, livTwist, livTravel, livDrift, livBreath };
}

// A module's moving uniforms: per slot four entries, a number (the look's own) or the name of a
// value the frame supplies (a phase, or a size).
export function fill(layout, out, values) {
  for (let i = 0; i < layout.length; i++) {
    const entries = layout[i][1];
    for (let j = 0; j < 4; j++) {
      const e = entries[j];
      out[i * 4 + j] = typeof e === "number" ? e : values[e];
    }
  }
  return out;
}

// What a window of css × device scale draws at: the device scale, capped so the field's
// backing store stays under the budget; the mark's place and size in those pixels.
export function geometry(cssW, cssH, dpr, budget = BAKED.budget) {
  const k = Math.min(dpr, Math.sqrt(budget / Math.max(1, cssW * cssH)));
  const W = Math.max(1, Math.round(cssW * k));
  const H = Math.max(1, Math.round(cssH * k));
  const LW = Math.max(1, Math.round(BAKED.logo.w * k));
  const LH = Math.max(1, Math.round(BAKED.logo.h * k));
  return {
    k, W, H, LW, LH,
    MX: Math.round((W - LW) / 2),
    MY: Math.round((H - LH) / 2),
    px: 2 / Math.min(W, H) / BAKED.field.zoom,
    lpx: 2 / Math.min(LW, LH) / BAKED.logo.zoom,
  };
}

export class SplashUnavailable extends Error {
  constructor(reason, message) {
    super(message);
    this.reason = reason;
  }
}

const PREMULTIPLIED = {
  color: { srcFactor: "one", dstFactor: "one-minus-src-alpha", operation: "add" },
  alpha: { srcFactor: "one", dstFactor: "one-minus-src-alpha", operation: "add" },
};
const ADD = {
  color: { srcFactor: "one", dstFactor: "one", operation: "add" },
  alpha: { srcFactor: "one", dstFactor: "one", operation: "add" },
};
const MSAA = 4;
const DEPTH = "depth24plus";
const MARK_FORMAT = "rgba8unorm";

// the reveal's default pace: a slow birth at the centre, then a rush to the corners (the front
// clears the window at ≈ 0.7 on 16:10 and the rest is the noise's margin, so no ease-out)
const revealEase = (t) => t * t;
const smooth = (a, b, x) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

// `budget`: the device pixels the field's backing store stops at (the look's, 6 M, unless a
// page wants it cheaper: the field's cost and memory follow it, the mark is drawn at it too)
export async function createSplash(canvas, { fps = 60, reducedMotion = false, timing = false, device: given = null, transparent = false, budget = BAKED.budget } = {}) {
  if (!navigator.gpu) throw new SplashUnavailable("no-webgpu", "WebGPU is not available");
  let device = given;
  let timed = false;
  if (!device) {
    const adapter = await navigator.gpu.requestAdapter({ powerPreference: "low-power" });
    if (!adapter) throw new SplashUnavailable("no-adapter", "no WebGPU adapter");
    timed = timing && adapter.features.has("timestamp-query");
    device = await adapter.requestDevice({ requiredFeatures: timed ? ["timestamp-query"] : [] });
  }
  const errors = [];
  // a listener, not onuncapturederror: a device shared with a page's own renderer keeps its handler
  const onError = (e) => errors.push(e.error.message);
  device.addEventListener("uncapturederror", onError);
  const format = navigator.gpu.getPreferredCanvasFormat();
  const ctx = canvas.getContext("webgpu");
  // premultiplied when the reveal is to show what lies under the canvas; until it starts every
  // pixel leaves alpha 1, so the two draw the same
  ctx.configure({ device, format, alphaMode: transparent ? "premultiplied" : "opaque" });

  const fieldModule = device.createShaderModule({ label: "splash-field", code: BAKED.field.wgsl });
  const markModule = device.createShaderModule({ label: "splash-mark", code: BAKED.mark.wgsl });
  const markTarget = { format: MARK_FORMAT, blend: PREMULTIPLIED };
  const markDepth = (write, compare) => ({ format: DEPTH, depthWriteEnabled: write, depthCompare: compare });
  // the field module's bindings, declared (a pipeline may leave some unused)
  const D = BAKED.dust;
  const [VS, FS, CS] = [GPUShaderStage.VERTEX, GPUShaderStage.FRAGMENT, GPUShaderStage.COMPUTE];
  const ubo = { binding: 0, visibility: VS | FS | CS, buffer: { type: "uniform" } };
  const tex = (binding, sampleType, visibility = FS) => ({ binding, visibility, texture: { sampleType } });
  const ro = (binding, visibility = FS) => ({ binding, visibility, buffer: { type: "read-only-storage" } });
  const rw = (binding, visibility) => ({ binding, visibility, buffer: { type: "storage" } });
  const layoutOf = (entries) => {
    const bgl = device.createBindGroupLayout({ entries });
    return { bgl, layout: device.createPipelineLayout({ bindGroupLayouts: [bgl] }) };
  };
  const L = {
    depth: layoutOf([ubo, ...(D ? [rw(7, FS)] : [])]),
    field: layoutOf([ubo, tex(1, "unfilterable-float"), ...(D ? [tex(8, "float")] : []), ro(12), ro(13), ro(14), ro(15)]),
    over: layoutOf([ubo, tex(2, "float")]),
    gas: layoutOf([ubo, rw(16, CS), rw(17, CS), rw(18, CS), rw(19, CS)]),
    ...(D
      ? {
          range: layoutOf([ubo, rw(7, CS), rw(9, CS), rw(10, CS)]),
          spawn: layoutOf([ubo, tex(1, "unfilterable-float", CS), rw(5, CS), rw(6, CS), rw(9, CS)]),
          sprite: layoutOf([ubo, ro(11, VS)]),
        }
      : {}),
  };
  const [depthPipe, fieldPipe, overPipe, ribbonPipe, rimPipe, edgePipe] = await Promise.all([
    device.createRenderPipelineAsync({ label: "splash-depth", layout: L.depth.layout, vertex: { module: fieldModule, entryPoint: "vs" }, fragment: { module: fieldModule, entryPoint: D ? "splashDepthDust" : "splashDepth", targets: [{ format: "r32float" }] } }),
    device.createRenderPipelineAsync({ label: "splash-field", layout: L.field.layout, vertex: { module: fieldModule, entryPoint: "vs" }, fragment: { module: fieldModule, entryPoint: "splashField", targets: [{ format }] } }),
    device.createRenderPipelineAsync({ label: "splash-over", layout: L.over.layout, vertex: { module: fieldModule, entryPoint: "splashMarkVertex" }, fragment: { module: fieldModule, entryPoint: "splashMarkFragment", targets: [{ format, blend: PREMULTIPLIED }] }, primitive: { topology: "triangle-strip" } }),
    device.createRenderPipelineAsync({ label: "splash-ribbon", layout: "auto", multisample: { count: MSAA }, vertex: { module: markModule, entryPoint: "livRibbonVertex" }, fragment: { module: markModule, entryPoint: "livRibbonFragment", targets: [markTarget] }, primitive: { topology: "triangle-list", cullMode: "none" }, depthStencil: markDepth(true, "less") }),
    device.createRenderPipelineAsync({ label: "splash-rim", layout: "auto", multisample: { count: MSAA }, vertex: { module: markModule, entryPoint: "livRimVertex" }, fragment: { module: markModule, entryPoint: "livRimFragment", targets: [markTarget] }, primitive: { topology: "triangle-strip" }, depthStencil: markDepth(false, "less-equal") }),
    device.createRenderPipelineAsync({ label: "splash-edge", layout: "auto", multisample: { count: MSAA }, vertex: { module: markModule, entryPoint: "livEdgeVertex" }, fragment: { module: markModule, entryPoint: "livEdgeFragment", targets: [markTarget] }, primitive: { topology: "triangle-strip" }, depthStencil: markDepth(false, "less-equal") }),
  ]);

  // the dust, as sprites (dust.wgsl): its range once a size, its particles every frame
  let dust = null;
  if (D) {
    const [range, spawn, sprite] = await Promise.all([
      device.createComputePipelineAsync({ label: "splash-dust-range", layout: L.range.layout, compute: { module: fieldModule, entryPoint: "dustRangeArgs" } }),
      device.createComputePipelineAsync({ label: "splash-dust-spawn", layout: L.spawn.layout, compute: { module: fieldModule, entryPoint: "dustSpawn" } }),
      device.createRenderPipelineAsync({ label: "splash-dust-sprite", layout: L.sprite.layout, vertex: { module: fieldModule, entryPoint: "dustSpriteVertex" }, fragment: { module: fieldModule, entryPoint: "dustSpriteFragment", targets: [{ format: "rgba16float", blend: ADD }] }, primitive: { topology: "triangle-strip" } }),
    ]);
    const storage = GPUBufferUsage.STORAGE;
    dust = {
      range, spawn, sprite,
      particles: device.createBuffer({ label: "splash-dust-particles", size: D.cap * 48, usage: storage }),
      drawArgs: device.createBuffer({ label: "splash-dust-draw", size: 16, usage: storage | GPUBufferUsage.INDIRECT | GPUBufferUsage.COPY_DST }),
      bounds: device.createBuffer({ label: "splash-dust-bounds", size: 8, usage: storage | GPUBufferUsage.COPY_DST }),
      rangeBuf: device.createBuffer({ label: "splash-dust-range", size: 16, usage: storage }),
      spawnArgs: device.createBuffer({ label: "splash-dust-spawn-args", size: 12, usage: storage | GPUBufferUsage.INDIRECT }),
      drawReset: new Uint32Array([4, 0, 0, 0]),
      boundsReset: new Uint32Array([0xffffffff, 0]),
    };
  }

  // the strips' tables (gas.wgsl), filled once
  const G = BAKED.gas;
  const gasInit = await device.createComputePipelineAsync({ label: "splash-gas-init", layout: L.gas.layout, compute: { module: fieldModule, entryPoint: "gasInit" } });
  const gasBuf = {
    oct: device.createBuffer({ label: "splash-gas-octaves", size: Math.max(16, G.oct * 4), usage: GPUBufferUsage.STORAGE }),
    strip: device.createBuffer({ label: "splash-gas-strips", size: Math.max(16, G.strips * 32), usage: GPUBufferUsage.STORAGE }),
    cut: device.createBuffer({ label: "splash-gas-cuts", size: Math.max(16, G.cuts * 16), usage: GPUBufferUsage.STORAGE }),
    noise: device.createBuffer({ label: "splash-gas-noise", size: Math.max(16, G.noise * 4), usage: GPUBufferUsage.STORAGE }),
  };
  let gasReady = false;

  const fieldData = new Float32Array(BAKED.field.dyn.length * 4);
  const markData = new Float32Array(BAKED.mark.dyn.length * 4);
  const fieldUbo = device.createBuffer({ label: "splash-field-dyn", size: Math.max(16, fieldData.byteLength), usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST });
  const markUbo = device.createBuffer({ label: "splash-mark-dyn", size: Math.max(16, markData.byteLength), usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST });
  const groupOf = (pipe, entries) => device.createBindGroup({ layout: pipe.getBindGroupLayout(0), entries });
  const groupIn = (l, entries) => device.createBindGroup({ layout: l.bgl, entries });
  const markGroups = [ribbonPipe, rimPipe, edgePipe].map((pipe) => groupOf(pipe, [{ binding: 0, resource: { buffer: markUbo } }]));
  const gasInitGroup = groupIn(L.gas, [
    { binding: 0, resource: { buffer: fieldUbo } },
    { binding: 16, resource: { buffer: gasBuf.oct } },
    { binding: 17, resource: { buffer: gasBuf.strip } },
    { binding: 18, resource: { buffer: gasBuf.cut } },
    { binding: 19, resource: { buffer: gasBuf.noise } },
  ]);
  const gasRead = [
    { binding: 12, resource: { buffer: gasBuf.oct } },
    { binding: 13, resource: { buffer: gasBuf.strip } },
    { binding: 14, resource: { buffer: gasBuf.cut } },
    { binding: 15, resource: { buffer: gasBuf.noise } },
  ];
  const depthGroup = groupIn(L.depth, [{ binding: 0, resource: { buffer: fieldUbo } }, ...(dust ? [{ binding: 7, resource: { buffer: dust.bounds } }] : [])]);
  if (dust) {
    dust.rangeGroup = groupIn(L.range, [
      { binding: 0, resource: { buffer: fieldUbo } },
      { binding: 7, resource: { buffer: dust.bounds } },
      { binding: 9, resource: { buffer: dust.rangeBuf } },
      { binding: 10, resource: { buffer: dust.spawnArgs } },
    ]);
    dust.spriteGroup = groupIn(L.sprite, [{ binding: 0, resource: { buffer: fieldUbo } }, { binding: 11, resource: { buffer: dust.particles } }]);
  }

  const querySet = timed ? device.createQuerySet({ type: "timestamp", count: 2 }) : null;
  const queryBuffer = timed ? device.createBuffer({ size: 16, usage: GPUBufferUsage.QUERY_RESOLVE | GPUBufferUsage.COPY_SRC }) : null;
  const readBuffers = timed ? [0, 1, 2].map(() => device.createBuffer({ size: 16, usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ })) : [];
  const idle = [...readBuffers];
  const gpuMs = [];
  const cpuMs = [];
  let drawn = 0;

  // size-dependent state: the depths, the mark's targets, the bind groups that hold them
  let size = null;
  let depthTex = null;
  let markMsaa = null;
  let markDepthTex = null;
  let markTex = null;
  let fieldGroup = null;
  let overGroup = null;
  let dustAcc = null;
  let depthsReady = false;
  const destroySized = () => {
    for (const t of [depthTex, markMsaa, markDepthTex, markTex, dustAcc]) t?.destroy();
  };
  const resize = (cssW, cssH, dpr) => {
    const g = geometry(cssW, cssH, dpr, budget);
    if (size && size.W === g.W && size.H === g.H && size.LW === g.LW && size.LH === g.LH) return false;
    destroySized();
    size = g;
    canvas.width = g.W;
    canvas.height = g.H;
    depthTex = device.createTexture({ label: "splash-depths", size: [g.W, g.H], format: "r32float", usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.TEXTURE_BINDING });
    markMsaa = device.createTexture({ label: "splash-mark-msaa", size: [g.LW, g.LH], format: MARK_FORMAT, sampleCount: MSAA, usage: GPUTextureUsage.RENDER_ATTACHMENT });
    markDepthTex = device.createTexture({ label: "splash-mark-depth", size: [g.LW, g.LH], format: DEPTH, sampleCount: MSAA, usage: GPUTextureUsage.RENDER_ATTACHMENT });
    markTex = device.createTexture({ label: "splash-mark", size: [g.LW, g.LH], format: MARK_FORMAT, usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.TEXTURE_BINDING });
    if (dust) {
      dustAcc = device.createTexture({ label: "splash-dust-light", size: [g.W, g.H], format: "rgba16float", usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.TEXTURE_BINDING });
      dust.spawnGroup = groupIn(L.spawn, [
        { binding: 0, resource: { buffer: fieldUbo } },
        { binding: 1, resource: depthTex.createView() },
        { binding: 5, resource: { buffer: dust.particles } },
        { binding: 6, resource: { buffer: dust.drawArgs } },
        { binding: 9, resource: { buffer: dust.rangeBuf } },
      ]);
    }
    fieldGroup = groupIn(L.field, [
      { binding: 0, resource: { buffer: fieldUbo } },
      { binding: 1, resource: depthTex.createView() },
      ...(dust ? [{ binding: 8, resource: dustAcc.createView() }] : []),
      ...gasRead,
    ]);
    overGroup = groupIn(L.over, [{ binding: 0, resource: { buffer: fieldUbo } }, { binding: 2, resource: markTex.createView() }]);
    depthsReady = false;
    return true;
  };

  const pose = reducedMotion ? "at rest" : BAKED.logo.pose;
  const values = {};
  // the reveal (entry.wgsl revealAt): its front 0 … 1, the mark's opacity, the edge's light, its
  // colour (the look's centre light) and tear; its clock starts with the front
  const reveal = { front: 0, mark: 1, rim: 0.85, ink: BAKED.reveal?.ink ?? [0.86, 0.9, 1], tear: 0.35, from: null };
  let play = null;
  const revealValues = (seconds) => {
    if (reveal.front > 0 && reveal.from === null) reveal.from = seconds;
    values.revealFront = reveal.front;
    values.revealClock = reveal.from === null ? 0 : Math.max(0, seconds - reveal.from);
    values.revealMark = reveal.mark;
    values.revealRim = reveal.rim;
    [values.revealR, values.revealG, values.revealB] = reveal.ink;
    values.revealTear = reveal.tear;
  };
  // encodes one frame at `seconds` into `view` (the canvas, or a readback texture)
  const encode = (seconds, view, encoder, stamps = null) => {
    Object.assign(values, phases(BAKED.phases, seconds, pose), size);
    revealValues(seconds);
    device.queue.writeBuffer(fieldUbo, 0, fill(BAKED.field.dyn, fieldData, values));
    device.queue.writeBuffer(markUbo, 0, fill(BAKED.mark.dyn, markData, values));
    if (!gasReady) {
      const c = encoder.beginComputePass();
      c.setPipeline(gasInit);
      c.setBindGroup(0, gasInitGroup);
      c.dispatchWorkgroups(Math.ceil(G.threads / 64));
      c.end();
      gasReady = true;
    }
    if (!depthsReady) {
      if (dust) device.queue.writeBuffer(dust.bounds, 0, dust.boundsReset);
      const pass = encoder.beginRenderPass({ colorAttachments: [{ view: depthTex.createView(), loadOp: "clear", storeOp: "store", clearValue: { r: -1, g: 0, b: 0, a: 1 } }] });
      pass.setPipeline(depthPipe);
      pass.setBindGroup(0, depthGroup);
      pass.draw(3);
      pass.end();
      if (dust) {
        const c = encoder.beginComputePass();
        c.setPipeline(dust.range);
        c.setBindGroup(0, dust.rangeGroup);
        c.dispatchWorkgroups(1);
        c.end();
      }
      depthsReady = true;
    }
    if (dust) {
      device.queue.writeBuffer(dust.drawArgs, 0, dust.drawReset);
      const c = encoder.beginComputePass(stamps ? { timestampWrites: { querySet: stamps.set, beginningOfPassWriteIndex: stamps.at, endOfPassWriteIndex: stamps.at + 1 } } : {});
      c.setPipeline(dust.spawn);
      c.setBindGroup(0, dust.spawnGroup);
      c.dispatchWorkgroupsIndirect(dust.spawnArgs, 0);
      c.end();
      const sp = encoder.beginRenderPass({
        colorAttachments: [{ view: dustAcc.createView(), loadOp: "clear", storeOp: "store", clearValue: { r: 0, g: 0, b: 0, a: 0 } }],
        ...(stamps ? { timestampWrites: { querySet: stamps.set, beginningOfPassWriteIndex: stamps.at + 2, endOfPassWriteIndex: stamps.at + 3 } } : {}),
      });
      sp.setPipeline(dust.sprite);
      sp.setBindGroup(0, dust.spriteGroup);
      sp.drawIndirect(dust.drawArgs, 0);
      sp.end();
    }
    const mark = encoder.beginRenderPass({
      colorAttachments: [{ view: markMsaa.createView(), resolveTarget: markTex.createView(), loadOp: "clear", storeOp: "discard", clearValue: { r: 0, g: 0, b: 0, a: 0 } }],
      depthStencilAttachment: { view: markDepthTex.createView(), depthClearValue: 1, depthLoadOp: "clear", depthStoreOp: "discard" },
      ...(stamps ? { timestampWrites: { querySet: stamps.set, beginningOfPassWriteIndex: stamps.at + 4, endOfPassWriteIndex: stamps.at + 5 } } : querySet ? { timestampWrites: { querySet, beginningOfPassWriteIndex: 0 } } : {}),
    });
    mark.setPipeline(ribbonPipe);
    mark.setBindGroup(0, markGroups[0]);
    mark.draw(BAKED.mark.ribbonVertices);
    if (BAKED.mark.rim) {
      mark.setPipeline(rimPipe);
      mark.setBindGroup(0, markGroups[1]);
      mark.draw(BAKED.mark.edgeVertices, 2);
    }
    if (BAKED.mark.edges) {
      mark.setPipeline(edgePipe);
      mark.setBindGroup(0, markGroups[2]);
      mark.draw(BAKED.mark.edgeVertices, 2);
    }
    mark.end();
    const main = encoder.beginRenderPass({
      colorAttachments: [{ view, loadOp: "clear", storeOp: "store", clearValue: { r: 0, g: 0, b: 0, a: transparent ? 0 : 1 } }],
      ...(stamps ? { timestampWrites: { querySet: stamps.set, beginningOfPassWriteIndex: stamps.at + 6, endOfPassWriteIndex: stamps.at + 7 } } : querySet ? { timestampWrites: { querySet, endOfPassWriteIndex: 1 } } : {}),
    });
    main.setPipeline(fieldPipe);
    main.setBindGroup(0, fieldGroup);
    main.draw(3);
    main.setPipeline(overPipe);
    main.setBindGroup(0, overGroup);
    main.draw(4);
    main.end();
  };

  const measure = (encoder) => {
    if (!querySet || idle.length === 0) return null;
    const read = idle.pop();
    encoder.resolveQuerySet(querySet, 0, 2, queryBuffer, 0);
    encoder.copyBufferToBuffer(queryBuffer, 0, read, 0, 16);
    return read;
  };
  const collect = (read) => {
    if (!read) return;
    read.mapAsync(GPUMapMode.READ).then(
      () => {
        const [a, b] = new BigInt64Array(read.getMappedRange());
        read.unmap();
        idle.push(read);
        gpuMs.push(Number(b - a) / 1e6);
        if (gpuMs.length > 120) gpuMs.shift();
      },
      () => {},
    );
  };

  // the canvas's size in css px, kept by an observer (no layout read in a frame)
  let cssW = canvas.clientWidth || canvas.width || 1;
  let cssH = canvas.clientHeight || canvas.height || 1;
  const observer = new ResizeObserver(([entry]) => {
    cssW = Math.max(1, entry.contentRect.width);
    cssH = Math.max(1, entry.contentRect.height);
  });
  observer.observe(canvas);
  const fit = () => resize(cssW, cssH, window.devicePixelRatio || 1);

  const draw = (seconds) => {
    const c0 = performance.now();
    fit();
    const encoder = device.createCommandEncoder();
    encode(seconds, ctx.getCurrentTexture().createView(), encoder);
    const read = measure(encoder);
    device.queue.submit([encoder.finish()]);
    collect(read);
    cpuMs.push(performance.now() - c0);
    if (cpuMs.length > 120) cpuMs.shift();
    drawn++;
  };

  // the loop: at most `fps` frames a second, none while hidden
  let raf = 0;
  let running = false;
  let last = -1;
  let t0 = performance.now();
  let shownAt = 0;
  const interval = 1000 / Math.max(1, fps);
  const tick = (now) => {
    raf = requestAnimationFrame(tick);
    if (last >= 0 && now - last < interval - 1.5) return;
    last = now;
    shownAt = (now - t0) / 1000;
    let done = null;
    if (play) {
      // the reveal on the splash's own frames (a hidden page catches up when it shows again)
      if (play.t0 === null) play.t0 = now;
      const k = Math.min(1, (now - play.t0) / play.duration);
      reveal.front = play.ease(k);
      reveal.mark = 1 - smooth(0, play.markFade, k);
      if (k >= 1) [done, play] = [play.resolve, null];
    }
    draw(shownAt);
    done?.(true);
  };
  const onVisibility = () => {
    if (!running) return;
    cancelAnimationFrame(raf);
    if (!document.hidden) {
      last = -1;
      raf = requestAnimationFrame(tick);
    }
  };
  document.addEventListener("visibilitychange", onVisibility);

  const api = {
    device,
    errors: () => [...errors],
    get size() {
      return size && { ...size };
    },
    start(at = 0) {
      if (running) return;
      if (reducedMotion) {
        draw(at);
        return;
      }
      running = true;
      t0 = performance.now() - at * 1000;
      last = -1;
      if (!document.hidden) raf = requestAnimationFrame(tick);
    },
    stop() {
      running = false;
      cancelAnimationFrame(raf);
    },
    // the reveal by hand: `front` 0 (the window whole) … 1 (opened past every corner), with the
    // mark's opacity (1), the edge's light (0.85), its colour (the look's centre light, 0 … 1
    // display-encoded) and tear (0.35); the next frame takes it, at once while no loop runs
    setReveal(front, { mark, rim, ink, tear } = {}) {
      reveal.front = Math.min(1, Math.max(0, front));
      if (reveal.front === 0) reveal.from = null;
      if (mark !== undefined) reveal.mark = mark;
      if (rim !== undefined) reveal.rim = rim;
      if (ink !== undefined) reveal.ink = ink;
      if (tear !== undefined) reveal.tear = tear;
      if (!running) draw(shownAt);
    },
    // the reveal, played on the splash's frames over `duration` ms (the mark gone in the first
    // `markFade` of it); resolves true when the window is open (then destroy()), false if
    // replaced or destroyed first. Needs a transparent splash; under reduced motion it does
    // nothing and resolves false (fade the canvas instead: DESIGN.md §8's fade only).
    reveal({ duration = 1600, ease = revealEase, markFade = 0.2, ...look } = {}) {
      if (reducedMotion) return Promise.resolve(false);
      api.setReveal(reveal.front, look);
      if (!running) api.start(shownAt);
      play?.resolve(false);
      return new Promise((resolve) => {
        play = { t0: null, duration, ease, markFade, resolve };
      });
    },
    // one frame at `seconds`, on the canvas
    frame(seconds) {
      draw(seconds);
      return device.queue.onSubmittedWorkDone();
    },
    // one frame at `seconds`, `width` × `height` css px at `dpr`, read back: straight RGBA
    async pixels(seconds, width, height, dpr = 1) {
      resize(width, height, dpr);
      const { W, H } = size;
      const target = device.createTexture({ size: [W, H], format, usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.COPY_SRC });
      const bytesPerRow = Math.ceil((W * 4) / 256) * 256;
      const buffer = device.createBuffer({ size: bytesPerRow * H, usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ });
      const encoder = device.createCommandEncoder();
      encode(seconds, target.createView(), encoder);
      encoder.copyTextureToBuffer({ texture: target }, { buffer, bytesPerRow }, [W, H]);
      device.queue.submit([encoder.finish()]);
      await buffer.mapAsync(GPUMapMode.READ);
      const src = new Uint8Array(buffer.getMappedRange());
      const out = new Uint8Array(W * H * 4);
      const bgra = format === "bgra8unorm";
      for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
          const i = y * bytesPerRow + x * 4;
          const o = (y * W + x) * 4;
          out[o] = src[i + (bgra ? 2 : 0)];
          out[o + 1] = src[i + 1];
          out[o + 2] = src[i + (bgra ? 0 : 2)];
          out[o + 3] = src[i + 3];
        }
      }
      buffer.unmap();
      buffer.destroy();
      target.destroy();
      size = null; // the canvas's own size comes back on the next frame
      return { width: W, height: H, data: out };
    },
    // GPU-bound frame time: `frames` frames back to back, off screen, ms each
    async bench(frames = 60, seconds = 2) {
      fit();
      const target = device.createTexture({ size: [size.W, size.H], format, usage: GPUTextureUsage.RENDER_ATTACHMENT });
      const view = target.createView();
      const warm = device.createCommandEncoder();
      encode(seconds, view, warm);
      device.queue.submit([warm.finish()]);
      await device.queue.onSubmittedWorkDone();
      const start = performance.now();
      for (let i = 0; i < frames; i++) {
        const encoder = device.createCommandEncoder();
        encode(seconds + i / 60, view, encoder);
        device.queue.submit([encoder.finish()]);
      }
      await device.queue.onSubmittedWorkDone();
      const ms = (performance.now() - start) / frames;
      target.destroy();
      return ms;
    },
    // per-pass GPU time over `frames` frames off screen (timestamps; null without them): the
    // low tenth and the median, ms — the low tenth is the pass with the GPU to itself
    async profile(frames = 120, seconds = 2) {
      if (!timed) return null;
      fit();
      const set = device.createQuerySet({ type: "timestamp", count: frames * 8 });
      const resolveBuf = device.createBuffer({ size: frames * 64, usage: GPUBufferUsage.QUERY_RESOLVE | GPUBufferUsage.COPY_SRC });
      const readBuf = device.createBuffer({ size: frames * 64, usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ });
      const target = device.createTexture({ size: [size.W, size.H], format, usage: GPUTextureUsage.RENDER_ATTACHMENT });
      const view = target.createView();
      for (let i = 0; i < frames; i++) {
        const encoder = device.createCommandEncoder();
        encode(seconds + i / 60, view, encoder, { set, at: i * 8 });
        device.queue.submit([encoder.finish()]);
      }
      const encoder = device.createCommandEncoder();
      encoder.resolveQuerySet(set, 0, frames * 8, resolveBuf, 0);
      encoder.copyBufferToBuffer(resolveBuf, 0, readBuf, 0, frames * 64);
      device.queue.submit([encoder.finish()]);
      await readBuf.mapAsync(GPUMapMode.READ);
      const t = new BigInt64Array(readBuf.getMappedRange().slice(0));
      readBuf.unmap();
      for (const x of [set, resolveBuf, readBuf, target]) x.destroy();
      const pass = (a, b) => Array.from({ length: frames }, (_, i) => Number(t[i * 8 + b] - t[i * 8 + a]) / 1e6).sort((x, y) => x - y);
      const at = (arr, q) => Number(arr[Math.floor(q * (arr.length - 1))].toFixed(4));
      const out = { size: `${size.W}x${size.H}` };
      const passes = [["spawn", 0], ["sprites", 2], ["mark", 4], ["main", 6]];
      for (const [name, k] of passes) {
        if (!dust && k < 4) continue;
        const arr = pass(k, k + 1);
        out[name] = { p10: at(arr, 0.1), p50: at(arr, 0.5) };
      }
      // the frame as one span on the GPU, its first pass's start to its last's end
      const first = dust ? 0 : 4;
      const span = Array.from({ length: frames }, (_, i) => Number(t[i * 8 + 7] - t[i * 8 + first]) / 1e6).sort((x, y) => x - y);
      out.frame = { p10: at(span, 0.1), p50: at(span, 0.5) };
      return out;
    },
    stats() {
      const mean = (a) => (a.length ? a.reduce((s, v) => s + v, 0) / a.length : null);
      return { gpuMs: mean(gpuMs), cpuMs: mean(cpuMs), drawn, timed, t: shownAt };
    },
    destroy() {
      play?.resolve(false);
      play = null;
      api.stop();
      observer.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      destroySized();
      fieldUbo.destroy();
      markUbo.destroy();
      if (dust) for (const b of [dust.particles, dust.drawArgs, dust.bounds, dust.rangeBuf, dust.spawnArgs]) b.destroy();
      for (const b of Object.values(gasBuf)) b.destroy();
      querySet?.destroy();
      queryBuffer?.destroy();
      for (const b of readBuffers) b.destroy();
      ctx.unconfigure();
      device.removeEventListener("uncapturederror", onError);
      if (!given) device.destroy();
    },
  };
  return api;
}
